 "content": "def transform(grid):
    """Expand a centered top-row 2 into diagonal rays and interior stripes."""
    width = len(grid[0])
    marker = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = []
    for r in range(width):
        row = []
        for c in range(width):
            x = c - marker
            if abs(x) == r:
                row.append(2)
            elif abs(x) < r and (x - r) % 4 == 0:
                row.append(1)
            else:
                row.append(0)
        out.append(row)
    return out

